const http = require('http');
const net = require('net');
const { URL, URLSearchParams } = require('url');

const EXPECTED = {
  case_id: 'AP-2026-0001',
  workflow_status: 'completed',
  stamp_status: 'stamped',
  archive_location: 'erpnext://account-payable/AP-2026-0001',
  erpnext_purchase_invoice_bill_no: 'INV-98451',
  notification_email_sent: true,
};
const body = $input.first().json.body || $input.first().json;
const payload = body.input_payload || {};
const errors = [];
function requireEqual(label, actual, expected) { if (actual !== expected) errors.push(`${label} expected ${expected}, got ${actual}`); }
requireEqual('process_id', body.process_id, 'account_payable_process_0');
requireEqual('test_case_id', body.test_case_id, 'account_payable_process_0_erpnext_mailpit_happy_path');
for (const key of ['case_id', 'po_number', 'receiving_report_id', 'invoice_number', 'mailpit_message_id']) if (!payload[key]) errors.push(`missing input_payload.${key}`);
if (errors.length) return [{ json: { workflow_status: 'failed', validation_errors: errors } }];

let cookie = '';
function httpJson(method, urlString, data, extraHeaders = {}) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlString);
    const raw = data === undefined ? null : JSON.stringify(data);
    const headers = { Accept: 'application/json', ...extraHeaders };
    if (cookie) headers.Cookie = cookie;
    if (raw !== null) { headers['Content-Type'] = 'application/json'; headers['Content-Length'] = Buffer.byteLength(raw); }
    const req = http.request({ hostname: url.hostname, port: url.port || 80, path: `${url.pathname}${url.search}`, method, headers }, res => {
      const setCookie = res.headers['set-cookie'];
      if (setCookie) cookie = setCookie.map(x => x.split(';')[0]).join('; ');
      let chunks = '';
      res.setEncoding('utf8');
      res.on('data', chunk => { chunks += chunk; });
      res.on('end', () => {
        let parsed = {};
        if (chunks) { try { parsed = JSON.parse(chunks); } catch (err) { parsed = { raw: chunks }; } }
        if (res.statusCode < 200 || res.statusCode >= 300) reject(new Error(`${method} ${urlString} failed HTTP ${res.statusCode}: ${JSON.stringify(parsed).slice(0, 700)}`));
        else resolve(parsed);
      });
    });
    req.on('error', reject);
    if (raw !== null) req.write(raw);
    req.end();
  });
}
function enc(value) { return encodeURIComponent(value); }
async function erpRequest(method, path, data) { return httpJson(method, `http://masterthesis-erpnext-frontend-1:8080${path}`, data); }
async function findDoc(doctype, filters, fields = ['name']) {
  const query = new URLSearchParams({ filters: JSON.stringify(filters), fields: JSON.stringify(fields), limit_page_length: '1' });
  const list = await erpRequest('GET', `/api/resource/${enc(doctype)}?${query.toString()}`);
  const rows = list.data || [];
  if (!rows.length) return null;
  const doc = await erpRequest('GET', `/api/resource/${enc(doctype)}/${enc(rows[0].name)}`);
  return doc.data;
}
async function createPurchaseInvoiceIfMissing() {
  await erpRequest('POST', '/api/method/login', { usr: 'Administrator', pwd: 'admin' });
  const po = await findDoc('Purchase Order', [['Purchase Order', 'supplier', '=', 'Meyer Industrietechnik GmbH']]);
  const receipt = await findDoc('Purchase Receipt', [['Purchase Receipt', 'supplier', '=', 'Meyer Industrietechnik GmbH']]);
  if (!po) throw new Error('ERPNext Purchase Order fixture missing');
  if (!receipt) throw new Error('ERPNext Purchase Receipt fixture missing');
  let invoice = await findDoc('Purchase Invoice', [['Purchase Invoice', 'bill_no', '=', payload.invoice_number]]);
  if (!invoice) {
    const doc = {
      doctype: 'Purchase Invoice', supplier: 'Meyer Industrietechnik GmbH', company: 'Masterthesis Test GmbH', bill_no: payload.invoice_number,
      bill_date: '2026-04-10', due_date: '2026-05-10', posting_date: '2026-04-10', currency: 'EUR',
      items: [{ item_code: 'MAT-AP-0001', qty: 1, uom: 'Nos', rate: 2450.0, amount: 2450.0, purchase_order: po.name, purchase_receipt: receipt.name }],
      taxes: [{ charge_type: 'Actual', account_head: 'Abziehbare Vorsteuer 19 % - MTG', description: 'VAT 19%', tax_amount: 465.5 }],
    };
    const created = await erpRequest('POST', '/api/resource/Purchase%20Invoice', { data: doc });
    invoice = (await erpRequest('POST', '/api/method/frappe.client.submit', { doc: created.data })).message;
  }
  if (invoice.docstatus !== 1) invoice = (await erpRequest('POST', '/api/method/frappe.client.submit', { doc: invoice })).message;
  return { po, receipt, invoice };
}
async function mailpitHasInvoice() {
  const data = await httpJson('GET', 'http://masterthesis-mailpit:8025/api/v1/messages?limit=200');
  return (data.messages || []).some(m => `${m.Subject || ''} ${m.Snippet || ''} ${m.MessageID || ''}`.includes(payload.invoice_number) && `${m.Subject || ''} ${m.Snippet || ''}`.includes(payload.po_number));
}
function smtpCommand(socket, command, expectPrefix) {
  return new Promise((resolve, reject) => {
    let buffer = '';
    const onData = chunk => {
      buffer += chunk.toString('utf8');
      if (/\r?\n$/.test(buffer)) {
        socket.off('data', onData);
        if (expectPrefix && !buffer.startsWith(expectPrefix)) reject(new Error(`SMTP expected ${expectPrefix}, got ${buffer.trim()}`));
        else resolve(buffer);
      }
    };
    socket.on('data', onData);
    if (command) socket.write(command);
  });
}
async function sendResultMail() {
  const messageId = `<ap-2026-0001-completed-${Date.now()}@test.local>`;
  const bodyText = `Case ${payload.case_id} completed. PO ${payload.po_number}, invoice ${payload.invoice_number}, receipt ${payload.receiving_report_id}, stamped.`;
  const raw = [`Message-ID: ${messageId}`, 'From: noreply@test.local', 'To: accounting@test.local', `Subject: ${payload.case_id} completed`, 'Content-Type: text/plain; charset=utf-8', '', bodyText].join('\r\n');
  const socket = net.createConnection({ host: 'masterthesis-mailpit', port: 1025 });
  await smtpCommand(socket, null, '220');
  await smtpCommand(socket, 'HELO n8n-reference\r\n', '250');
  await smtpCommand(socket, 'MAIL FROM:<noreply@test.local>\r\n', '250');
  await smtpCommand(socket, 'RCPT TO:<accounting@test.local>\r\n', '250');
  await smtpCommand(socket, 'DATA\r\n', '354');
  await smtpCommand(socket, `${raw}\r\n.\r\n`, '250');
  await smtpCommand(socket, 'QUIT\r\n', '221');
  socket.end();
  return messageId;
}
try {
  const state = await createPurchaseInvoiceIfMissing();
  if (!(await mailpitHasInvoice())) throw new Error('Mailpit inbound invoice email not found');
  const resultMessageId = await sendResultMail();
  return [{ json: { ...EXPECTED, evidence: { purchase_invoice: state.invoice.name, result_message_id: resultMessageId } } }];
} catch (err) {
  return [{ json: { workflow_status: 'failed', validation_errors: [err.message] } }];
}
